"""Every case in conformance/protocol.v1.json, generated by the TypeScript reference."""

import json
import unittest
from pathlib import Path
from typing import Any

from super_protocol import (
    SSEParser,
    StreamFrameTooLarge,
    is_terminal_event,
    validate_chart_card_spec,
    validate_editor_card_spec,
    validate_plugin_manifest,
)

DATA = json.loads((Path(__file__).resolve().parents[3] / "conformance" / "protocol.v1.json").read_text())


def run_sse(case: dict[str, Any]) -> dict[str, Any]:
    parser = SSEParser(case["max_frame_bytes"]) if "max_frame_bytes" in case else SSEParser()
    frames: list[dict[str, str]] = []
    try:
        for chunk in case["chunks"]:
            frames += [{"event": f.event, "data": f.data} for f in parser.feed(bytes.fromhex(chunk))]
        frames += [{"event": f.event, "data": f.data} for f in parser.finish()]
    except StreamFrameTooLarge as e:
        return {"frames": frames, "error": e.code}
    return {"frames": frames}


class Conformance(unittest.TestCase):
    def check(self, key: str, fn: Any, minimum: int) -> None:
        cases = DATA[key]
        self.assertGreaterEqual(len(cases), minimum)
        for i, case in enumerate(cases):
            with self.subTest(case=key, i=i):
                self.assertEqual(fn(case), case["expect"])

    def test_plugin_manifest(self) -> None:
        self.check("plugin_manifest", lambda c: validate_plugin_manifest(c["value"]), 100)

    def test_editor_card(self) -> None:
        self.check("editor_card", lambda c: validate_editor_card_spec(c["value"]), 30)

    def test_chart_card(self) -> None:
        self.check("chart_card", lambda c: validate_chart_card_spec(c["value"]), 200)

    def test_terminal_event(self) -> None:
        self.check("terminal_event", lambda c: is_terminal_event(c["type"]), 8)

    def test_sse(self) -> None:
        self.check("sse", run_sse, 300)
        self.assertGreaterEqual(sum(1 for c in DATA["sse"] if "error" in c["expect"]), 10)


if __name__ == "__main__":
    unittest.main()
